/** Presentation/filter label derived from outboundState. Stored separately from smsMetadata so Twenty can filter, group, and build views from first-class fields. */
export type AgencyProspectOutboundLabelEnum = 'NEEDS_ENRICHMENT' | 'NEEDS_VIDEO' | 'READY_FOR_SMS' | 'SMS_IN_PROGRESS' | 'FOLLOW_UP_DUE' | 'HUMAN_REVIEW' | 'POSITIVE_REPLY' | 'NEGATIVE_REPLY' | 'DO_NOT_CONTACT' | 'DELIVERY_FAILED'


/** Qualified or Disqualified */
export type AgencyProspectQualificationStatusEnum = 'QUALIFIED' | 'DISQUALIFIED'


/** Pending until checked; Validated if the number is on WhatsApp; Rejected if it is not */
export type AgencyProspectWhatsappStatusEnum = 'PENDING' | 'VALIDATED' | 'REJECTED'


/** Lifecycle of the dynamic-data enrichment for the template site: Queued → Enriching → Enriched, or Failed */
export type AgencyProspectEnrichmentStatusEnum = 'QUEUED' | 'ENRICHING' | 'ENRICHED' | 'FAILED'

export type AgencyProspectLeadSourceEnum = 'HIRING_SIGNAL' | 'LOVABLE_SITE' | 'WEAK_SITE' | 'REFERRAL' | 'MANUAL'

export type AgencyProspectUtmSourceEnum = 'OUTBOUND' | 'INBOUND' | 'BLENDED'


/** Lifecycle position of the prospect in the outbound SMS state machine. See declarative label/state contract. */
export type AgencyProspectOutboundStateEnum = 'NEW' | 'ENRICHED' | 'VIDEO_READY' | 'QUEUED' | 'SENDING' | 'AWAITING_DELIVERY' | 'AWAITING_REPLY' | 'REPLIED' | 'QUALIFIED' | 'BOOKED' | 'COMPLETED' | 'PAUSED' | 'OPTED_OUT' | 'FAILED'

export type AgencyProspectOwnershipTypeEnum = 'FAMILY_OWNED' | 'OWNER_OPERATED' | 'PE_BACKED' | 'SUBSIDIARY' | 'ENTERPRISE' | 'UNKNOWN'

export type AgencyProspectDecisionPathEnum = 'OWNER_DECIDES' | 'NEEDS_LEADERSHIP_TEAM' | 'NEEDS_PARENT' | 'UNCLEAR'

export type AgencyProspectCompanySizeEnum = 'MICRO' | 'SMALL' | 'MID' | 'LARGE' | 'ENTERPRISE'


/** Call Now = 2+ sources agree, dial by name. Verify First = 1 source, confirm on the main line. US Importer = from our shipment data. Pennsylvania = found by the PA expansion. Warm Intro = ships with a company we know (named in the field note). Direct Phone = decision maker's own line. Verified Email = passed a deliverability check. Forwarder/3PL, Distributor, Manufacturer = business type. Full glossary: databrokering/gtm/docs/DATA_PLAY_TAGS.md */
export type AgencyProspectDataPlayTagsEnum = 'CALL_NOW' | 'VERIFY_FIRST' | 'US_IMPORTER' | 'PENNSYLVANIA' | 'WARM_INTRO' | 'DIRECT_PHONE' | 'VERIFIED_EMAIL' | 'FORWARDER_3PL' | 'DISTRIBUTOR' | 'MANUFACTURER' | 'DIRECT_PHONE_LOCAL' | 'READY_TO_DIAL' | 'NEEDS_RESEARCH'


/** Lifecycle of the cap-video walkthrough for this lead: None → Queued → Recording → Rendered → Attached, or Failed */
export type AgencyProspectVideoStatusEnum = 'NONE' | 'QUEUED' | 'RECORDING' | 'RENDERED' | 'ATTACHED' | 'FAILED'


/** Industry segment used to pick a template site */
export type AgencyProspectLabelEnum = 'AUTO_PAINT_AND_BODY_SHOPS' | 'WINDOW_TINTING' | 'AUTO_DETAILING' | 'GENERAL_TRADES' | 'NURSERY_SCHOOL' | 'JUNK_REMOVAL'

export type AgencyProspectOfferEnum = 'MARKETING' | 'JOB_PLACEMENT' | 'BOTH'


/** Status from manual cold calling workflow (separate from SMS outbound pipeline) */
export type AgencyProspectColdCallStatusEnum = 'NEW' | 'CONTACTED' | 'INTERESTED' | 'NOT_INTERESTED' | 'CALLBACK' | 'CONVERTED' | 'DO_NOT_CONTACT'


