/** LEAD = quiz + booking (default, existing behaviour). RECRUITMENT = career questionnaire + video submission, no Calendly. */
export type AgencyOfferFunnelTypeEnum = 'LEAD' | 'RECRUITMENT'


/** DRAFT / ACTIVE / PAUSED */
export type AgencyOfferStatusEnum = 'DRAFT' | 'ACTIVE' | 'PAUSED'


/** PROSPECT = use the prospect record videoUrl; CUSTOM = use this offer videoUrl for the whole industry. */
export type AgencyOfferVideoModeEnum = 'PROSPECT' | 'CUSTOM'


/** Industry this offer serves (INDUSTRY:{id} rows). */
export type AgencyOfferIndustryIdEnum = 'AUTO_PAINT_AND_BODY_SHOPS' | 'WINDOW_TINTING' | 'AUTO_DETAILING' | 'GENERAL_TRADES'


/** CONSULTATION / PRICING / CUSTOM (Twenty requires UPPER_CASE values) */
export type AgencyOfferCtaTypeEnum = 'CONSULTATION' | 'PRICING' | 'CUSTOM'


/** A guided one-page lander tied to a campaign — testimonials, CTA, video. */
export interface AgencyOffer {
    /** Name */
    name?: Scalars['String']
    /** ID */
    id: Scalars['UUID']
    /** Creation date */
    createdAt: Scalars['DateTime']
    /** The creator of the record */
    createdBy: Actor
    /** Deletion date */
    deletedAt?: Scalars['DateTime']
    /** Position */
    position: Scalars['Position']
    /** Last time the record was changed */
    updatedAt: Scalars['DateTime']
    /** The workspace member who last updated the record */
    updatedBy: Actor
    /** Search vector */
    searchVector?: Scalars['TSVector']
    /** LEAD = quiz + booking (default, existing behaviour). RECRUITMENT = career questionnaire + video submission, no Calendly. */
    funnelType?: AgencyOfferFunnelTypeEnum
    /** Disqualified page blocks JSON */
    disqualifiedConfig?: Scalars['JSON']
    /** Video-submission copy: { videoPrompt, videoLabel, videoPlaceholder, videoRequired, submitNote, submittedHeading, submittedBody } */
    applicationConfig?: Scalars['JSON']
    /** Brand mark image URL rendered left of the brand name above the hero H1. */
    brandLogoUrl?: Scalars['String']
    /** Per-UTM text swaps Record */
    utmSwaps?: Scalars['JSON']
    /** Quiz steps JSON for offer funnel - fed into Quiz.tsx */
    quizConfig?: Scalars['JSON']
    /** Six-word service line under the brand name, dynamically per offer. */
    brandSub?: Scalars['String']
    /** Thank-you page blocks JSON */
    thankYouConfig?: Scalars['JSON']
    /** Brand header name rendered above the hero H1 (e.g. ListeningKit). */
    brandName?: Scalars['String']
    /** Hero section lede paragraph */
    heroLede?: RichText
    /** DRAFT / ACTIVE / PAUSED */
    status?: AgencyOfferStatusEnum
    /** PROSPECT = use the prospect record videoUrl; CUSTOM = use this offer videoUrl for the whole industry. */
    videoMode?: AgencyOfferVideoModeEnum
    /** Worked-with logo carousel: [{src, alt}] SVG/IMG URLs rendered navy under the quiz */
    mediaLogos?: Scalars['JSON']
    /** Logo carousel H1 HTML (RichEditor). Falls back to default when blank. */
    carouselHeading?: Scalars['String']
    /** Offer title */
    title?: Scalars['String']
    /** Logo carousel description markdown (RichEditor, {{area}} supported), rendered under the marquee. */
    carouselDesc?: RichText
    /** Calendly link shown in iframe at end of quiz */
    calendlyUrl?: Scalars['String']
    /** Hero section H1 heading */
    heroH1?: Scalars['String']
    /** Industry this offer serves (INDUSTRY:{id} rows). */
    industryId?: AgencyOfferIndustryIdEnum
    /** Facebook Meta Pixel ID for this offer (fires PageView + Lead where fbLead true) */
    metaPixelId?: Scalars['String']
    /** VSL video URL */
    videoUrl?: Links
    /** CONSULTATION / PRICING / CUSTOM (Twenty requires UPPER_CASE values) */
    ctaType?: AgencyOfferCtaTypeEnum
    /** Slug of the agencyCareers row this funnel recruits for (e.g. cold-caller-appointment-setter). The questionnaire and role copy come from that record. */
    careerSlug?: Scalars['String']
    /** AgencyOffers tied to the Timeline Activity */
    timelineActivities?: TimelineActivityConnection
    /** AgencyOffers tied to the Attachment */
    attachments?: AttachmentConnection
    /** AgencyOffers tied to the Note Target */
    noteTargets?: NoteTargetConnection
    /** AgencyOffers tied to the Task Target */
    taskTargets?: TaskTargetConnection
    /** AgencyOffers tied to the Agent chat thread target */
    agentChatThreadTargets?: AgentChatThreadTargetConnection
    __typename: 'AgencyOffer'
}


