/** Social media accounts */
export interface SocialAccountGroupByInput {
/** Name */
name?: (Scalars['Boolean'] | null),
/** Creation date */
createdAt?: (GroupByDateGranularityInput | null),
/** The creator of the record */
createdBy?: (ActorGroupByInput | null),
/** Last time the record was changed */
updatedAt?: (GroupByDateGranularityInput | null),
/** The workspace member who last updated the record */
updatedBy?: (ActorGroupByInput | null),platform?: (Scalars['Boolean'] | null),
/** log-cli: the Facebook access token the vendor delivered. A credential: never print it */
accessToken?: (Scalars['Boolean'] | null),accountName?: (Scalars['Boolean'] | null),
/** log-cli: when the account's day of warm-up began (rule 35) */
warmupStartedAt?: (GroupByDateGranularityInput | null),
/** log-cli */
purchasedAt?: (GroupByDateGranularityInput | null),
/** log-cli: country of that exit IP. Must equal homeCountry */
proxyExitCountry?: (Scalars['Boolean'] | null),
/** log-cli: when the warm-up ended and the account was attached to its host (rule 35) */
warmedAt?: (GroupByDateGranularityInput | null),
/** log-cli: usable are ACTIVE and WARMING. BANNED and DEAD are terminal and never cleared. Rows are never deleted */
accountStatus?: (Scalars['Boolean'] | null),
/** log-cli */
statusChangedAt?: (GroupByDateGranularityInput | null),
/** log-cli: where the lifecycle machine has the account, e.g. onboarding.warming or host.watching (rule 35) */
lifecycleState?: (Scalars['Boolean'] | null),
/** log-cli: what the page said */
statusDetail?: (Scalars['Boolean'] | null),
/** log-cli: last proxy gate run */
proxyCheckedAt?: (GroupByDateGranularityInput | null),
/** log-cli: the browser the vendor used. Reference only: launches use deviceProfile (rule 15) */
vendorUserAgent?: (Scalars['Boolean'] | null),linkedTo?: (Scalars['Boolean'] | null),
/** log-cli: listings per day (3 when empty) */
dailyListingCap?: (Scalars['Boolean'] | null),
/** log-cli: local hour runs stop, e.g. 22. Empty: 22:00 */
activeHoursEnd?: (Scalars['Boolean'] | null),
/** log-cli: when `log profile setup --live` last saved the profile and cover photo */
profileSetAt?: (GroupByDateGranularityInput | null),
/** log-cli: the login state Facebook's own page gave the saved session on the last direct-API call (fbk's bootstrap: loggedIn, loggedOut, checkpoint, unknown, accountWarning). accountStatus stays the browser lifecycle */
sessionState?: (Scalars['Boolean'] | null),
/** log-cli: when sessionState was last read from Facebook by the direct-API engine */
sessionCheckedAt?: (GroupByDateGranularityInput | null),
/** log-cli: local hour runs may start, e.g. 8 or 8.5. Empty: 08:00 */
activeHoursStart?: (Scalars['Boolean'] | null),
/** log-cli: the product page it was bought from */
vendorListingUrl?: (Scalars['Boolean'] | null),
/** log-cli: ISO 3166 alpha-2 (IE). The proxy exit and every listing must be in this country */
homeCountry?: (Scalars['Boolean'] | null),
/** log-cli: exit IP seen through the proxy at the last check */
proxyExitIp?: (Scalars['Boolean'] | null),phoneNumber?: (Scalars['Boolean'] | null),
/** log-cli: the name `log profile setup` gives the profile, e.g. Allentown Trash (rule 28). Facebook reviews name changes and allows about one per 60 days */
profileName?: (Scalars['Boolean'] | null),
/** log-cli: when the profile was renamed to profileName */
profileNamedAt?: (GroupByDateGranularityInput | null),
/** log-cli: when the account's Marketplace location was confirmed in its home city */
marketplaceLocationAt?: (GroupByDateGranularityInput | null),
/** log-cli: where the account lives, e.g. Galway */
homeCity?: (Scalars['Boolean'] | null),
/** Proxy URL pinned to this social account (e.g. http://user:pass@host:port) */
proxy?: (Scalars['Boolean'] | null),
/** log-cli: the vendor order or invoice id */
vendorOrderId?: (Scalars['Boolean'] | null),
/** log-cli: the 6-digit PIN for the account's encrypted chats (Messenger's Create a PIN), set by matt with log facebook messenger pin (a Clack prompt). A credential: never print it */
messengerPin?: (Scalars['Boolean'] | null),
/** log-cli: the cover (background) photo `log profile setup` uploads (a URL or a local path) */
coverPhoto?: (Scalars['Boolean'] | null),emailPassword?: (Scalars['Boolean'] | null),email?: (Scalars['Boolean'] | null),
/** log-cli: which browser runs this account: adsPower or camoufox (empty: camoufox, rule 42) */
browserDriver?: (Scalars['Boolean'] | null),
/** log-cli: the profile picture `log profile setup` uploads (a URL or a local path). Real-looking, not a logo (rule 28) */
profilePhoto?: (Scalars['Boolean'] | null),
/** log-cli: who sold the account, as named in docs/vendors (e.g. NPPR Team Shop) */
vendor?: (Scalars['Boolean'] | null),
/** log-cli: used to pick the least recently used replacement */
lastPostedAt?: (GroupByDateGranularityInput | null),
/** log-cli: the account's AdsPower profile id (`log adsPower sync`). The profile holds no proxy, password or cookies: those stay in Twenty */
adsPowerProfileId?: (Scalars['Boolean'] | null),
/** log-cli: error catalog code behind the status (log errors --code <code>) */
statusReason?: (Scalars['Boolean'] | null),password?: (Scalars['Boolean'] | null),
/** log-cli: the TOTP (authenticator) secret the vendor delivered. A credential: never print it */
totpSecret?: (Scalars['Boolean'] | null),profileUrl?: (Scalars['Boolean'] | null)}


/** log-cli: a Facebook group, on one socialAccount */
